INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_ADJECTIVE','Laureate');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_ATTACKED_1','Then your boasts shall be tested. Our citizens have defended greater things than your ambition.');
