INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CIV','The Laureate Commonwealth');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CIV5_HEADING_1','A Republic of Earned Honor');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CIV5_TEXT_1','The Laureate Commonwealth is an imagined ancient republic founded on the laurel wreath: the evergreen sign of victory, honor and lasting achievement. Its citizens celebrate the architect beside the soldier and the poet beside the scholar. Victory is not merely the conquest of an enemy. Victory is the recognition of excellence.[NEWLINE][NEWLINE]Daphne began as a sanctuary where rival communities deposited records of public service. A common charter transformed ceremonial judges into elected magistrates. Laurea, Keeper of the Unfading Crown, safeguards the charter and presides over the recognition of deeds. Her crown belongs to the office, and the office belongs to the citizens.[NEWLINE][NEWLINE]The Evergreen Crown awards normal Golden Age Points for completed global World Wonders (40 + 10 times current Era index), newly created Great People (20 + 5 times Era), and military units first reaching Level 3 (10 + 2 times Era). Ancient is Era 0. Instant rewards use the game speed GreatPeoplePercent, matching the native Golden Age threshold scaling; fractions round down. National and Team Wonders, captured Wonders, captured Great People and replacement units earn no new creation reward. Great People are recognized after native creation/conversion settles, by the next owner-turn boundary or when expended.[NEWLINE][NEWLINE]Golden Ages add 15 percentage points to city Great Person generation and to military combat XP. These modifiers follow the native additive policy system and end with the Golden Age. General/Admiral combat meters and Prophet Faith thresholds are not city specialist generation. Halls add one unscaled point per functioning building per owner turn. The ordinary engine checks the Golden Age threshold on its next normal Golden Age processing step; no custom timer or threshold is used.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CIV_PEDIA','The Laureate Commonwealth is an imagined ancient republic founded on the laurel wreath: the evergreen sign of victory, honor and lasting achievement. Its citizens celebrate the architect beside the soldier and the poet beside the scholar. Victory is not merely the conquest of an enemy. Victory is the recognition of excellence.[NEWLINE][NEWLINE]Daphne began as a sanctuary where rival communities deposited records of public service. A common charter transformed ceremonial judges into elected magistrates. Laurea, Keeper of the Unfading Crown, safeguards the charter and presides over the recognition of deeds. Her crown belongs to the office, and the office belongs to the citizens.[NEWLINE][NEWLINE]The Evergreen Crown awards normal Golden Age Points for completed global World Wonders (40 + 10 times current Era index), newly created Great People (20 + 5 times Era), and military units first reaching Level 3 (10 + 2 times Era). Ancient is Era 0. Instant rewards use the game speed GreatPeoplePercent, matching the native Golden Age threshold scaling; fractions round down. National and Team Wonders, captured Wonders, captured Great People and replacement units earn no new creation reward. Great People are recognized after native creation/conversion settles, by the next owner-turn boundary or when expended.[NEWLINE][NEWLINE]Golden Ages add 15 percentage points to city Great Person generation and to military combat XP. These modifiers follow the native additive policy system and end with the Golden Age. General/Admiral combat meters and Prophet Faith thresholds are not city specialist generation. Halls add one unscaled point per functioning building per owner turn. The ordinary engine checks the Golden Age threshold on its next normal Golden Age processing step; no custom timer or threshold is used.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CROWN','Crowning Blow');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_CROWN_HELP','+15% Strength when attacking wounded enemy units. No wounded-target bonus against cities or on defense. Heal 15 HP after killing a hostile military unit, capped at maximum HP. Retained on upgrade.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_DAWN','Laurea, Keeper of the Unfading Crown, your Commonwealth looks to you.[NEWLINE][NEWLINE]In Daphne, the wreath honors the builder, the scholar, the artist and the veteran alike. Your ancestors raised a republic where deeds outlive ambition and excellence serves the common good.[NEWLINE][NEWLINE]Build something magnificent. Create someone extraordinary. Train a legendary warrior. Let their achievements kindle an age of prosperity, and let that prosperity inspire still greater work.[NEWLINE][NEWLINE]Will your people earn an unfading place in history?');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_DEFEAT_1','The crown passes from my hands. May those who remember us honor what we achieved, and learn from what we failed to defend.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_FRIENDLY_1','Your achievements have reached Daphne before you. Come, there is much we may learn from each other.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_GP_MARK','Great Person Already Recognized');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_GP_MARK_HELP','Internal lifetime recognition marker. No combat or yield effect.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_GREETING_1','Greetings. I am Laurea, Keeper of the Unfading Crown. Among our people, greatness is neither inherited nor bestowed. It must be earned. Tell me, stranger, what deeds shall history remember of you?');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_HALL','Hall of Laurels');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_HALL_HELP','Replaces Amphitheater and retains all active Amphitheater effects, requirements and its Great Work of Writing slot. Adds +1 Local Happiness and +1 [ICON_GOLDEN_AGE] Golden Age Point each owner turn while functioning. Multiple Halls stack. No points during resistance, razing or empire anarchy.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_HALL_PEDIA','Marble colonnades shelter inscribed accounts of service, statues of citizens and golden wreaths dedicated to great works. The Hall is part theater, part archive and part civic forum. No family owns a hereditary place within it; every name must be supported by an achievement.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_HALL_STRATEGY','Build Halls to honor writers, builders and veterans. Their local Happiness follows ordinary population limits. Each functioning Hall adds one point directly to the normal Golden Age meter, even during a Golden Age; its point is separate from Culture.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_HOSTILE_1','We keep careful records. Your words will require better deeds to support them.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_LAUREA_HEADING_1','Greatness Must Be Earned');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_LAUREA_LIVED','The Age of the Commonwealth');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_LAUREA_NAME','Laurea');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_LAUREA_SUBTITLE','Keeper of the Unfading Crown');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_LAUREA_TEXT_1','Laurea, Keeper of the Unfading Crown, leads through disciplined example. Proud, cultured and competitive, she prizes literature, magnificent architecture and military service. Empty boasts and dishonor receive a colder welcome than honest failure.[NEWLINE][NEWLINE]Her white robes symbolize impartial judgment; green recalls the republic''s enduring charter, and gold the achievements entrusted to its memory. Laurea insists that greatness can be taught, tested and renewed, but never inherited.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_LAUREA_TITLES_1','Keeper of the Unfading Crown');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_LEADER','Laurea');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_LEADER_PEDIA','Laurea, Keeper of the Unfading Crown, leads through disciplined example. Proud, cultured and competitive, she prizes literature, magnificent architecture and military service. Empty boasts and dishonor receive a colder welcome than honest failure.[NEWLINE][NEWLINE]Her white robes symbolize impartial judgment; green recalls the republic''s enduring charter, and gold the achievements entrusted to its memory. Laurea insists that greatness can be taught, tested and renewed, but never inherited.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_NEUTRAL_1','The council is listening. What undertaking brings you before the Commonwealth?');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_NOTICE_GOLDEN','During this Golden Age, Great People are generated 15% faster in cities and military units gain 15% more combat experience.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_NOTICE_PERSON','A newly created {1_Name} has earned {2_Num} [ICON_GOLDEN_AGE] Golden Age Points.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_NOTICE_TITLE','The Evergreen Crown');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_NOTICE_VETERAN','{1_Name} has earned its first laurel, granting {2_Num} [ICON_GOLDEN_AGE] Golden Age Points.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_NOTICE_WONDER','Completing {1_Name} has earned {2_Num} [ICON_GOLDEN_AGE] Golden Age Points.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_PEACE_1','Let this peace be a deed worthy of remembrance. Our people have greater work before them.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_PEACE_OFFER_1','We have measured each other in war. Let us now compete in the works that endure.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_POLICY','Golden Excellence');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_POLICY_HELP','Automatic Laureate Golden Age modifier: +15% city Great Person generation and +15% combat experience. Cannot be adopted.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_SHORT','Laureate Commonwealth');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_SPY_1','Ilex');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_SPY_10','Phaedra');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_SPY_2','Clio');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_SPY_3','Dorian');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_SPY_4','Ianthe');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_SPY_5','Lysander');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_SPY_6','Thalia');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_SPY_7','Nestor');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_SPY_8','Eirene');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_SPY_9','Cassia');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_STRATEGY','Pursue Culture through Wonders, Great People and a disciplined army. The Evergreen Crown accelerates normal Golden Age progress without extending Golden Ages. Build Halls of Laurels for steady progress, and use Champions to finish wounded enemies. Technology, expansion and careful positioning remain essential.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_TRADE_1','A fair exchange, honestly concluded. May both our peoples prosper.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_TRAIT','The Evergreen Crown');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_TRAIT_HELP','World Wonders earn 40 + 10 per Era [ICON_GOLDEN_AGE] Golden Age Points; Great People earn 20 + 5 per Era; military units first reaching Level 3 earn 10 + 2 per Era. Era starts at 0; instant awards scale with game speed. During Golden Ages: +15% Great Person generation in cities and +15% military combat experience.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_UNIT','Laureate Champion');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_UNIT_HELP','Replaces Swordsman. Retains the active Swordsman''s cost, Strength, Movement, Iron requirement, promotions and upgrades. Crowning Blow: +15% Strength when attacking wounded enemy units; heals 15 HP after killing an enemy military unit. Crowning Blow survives upgrades.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_UNIT_PEDIA','The Commonwealth crowns its veterans only after their deeds have been witnessed. A Champion wears practical armor, carries the ordinary infantry sword and bears a small wreath as a public obligation: excellence must be renewed in service, never presumed from rank.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_UNIT_STRATEGY','Let other units wound the enemy, then commit the Champion to a decisive attack. Crowning Blow grants no advantage against healthy units, cities or while defending. Its kill healing supports successive engagements; Iron and normal Swordsman technology are still required.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_VETERAN','Laurel Already Awarded');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_VETERAN_HELP','This unit has already received its once-per-lifetime Level 3 recognition. No combat effect. Retained through upgrades and transfers.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LC_WAR_1','You have mistaken restraint for weakness. Let the record show that the Commonwealth answered your dishonor with resolve.');
